import "pe"
rule cil_vb_string_array_command_launch {
  strings:
    $dispatch = { 11 ?? 72 ?? ?? ?? 70 16 28 ?? ?? ?? 0A
                  16 33 11 06 17 9A 16 16 15
                  28 ?? ?? ?? 0A 26 38 ?? ?? ?? ?? }
    $vb = "Microsoft.VisualBasic" ascii fullword
    $interaction = "Interaction" ascii fullword
    $shell = "Shell" ascii fullword
    $compare = "CompareString" ascii fullword
  condition:
    for any s in pe.sections : (
      s.name == ".text" and
      for all of them : (
        $ in (s.raw_data_offset .. s.raw_data_offset + s.raw_data_size - 1)
      )
    )
}

